    "code": "{\n  \"version\": \"0.4\",\n  \"title\": \"UAS - سکشن گرید بنتو با تب‌های تعاملی (Bento Services Grid Section)\",\n  \"type\": \"container\",\n  \"content\": [\n    {\n      \"id\": \"uas_cnt_bento_services_01\",\n      \"elType\": \"container\",\n      \"isInner\": false,\n      \"settings\": {\n        \"padding\": {\n          \"unit\": \"px\",\n          \"top\": \"70\",\n          \"right\": \"20\",\n          \"bottom\": \"70\",\n          \"left\": \"20\"\n        },\n        \"background_background\": \"classic\",\n        \"background_color\": \"#FFFFFF\",\n        \"content_width\": \"boxed\",\n        \"flex_direction\": \"column\",\n        \"flex_align_items\": \"stretch\",\n        \"flex_justify_content\": \"center\"\n      },\n      \"elements\": [\n        {\n          \"id\": \"uas_wid_bento_services_01\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"uas_bento_tabs\",\n          \"settings\": {\n            \"bento_list\": [\n              {\n                \"category_slug\": \"conversion\",\n                \"card_span\": \"span-2\",\n                \"icon\": \"⚡\",\n                \"title\": \"سوییچر هوشمند پلن‌ها با تخفیف سالانه\",\n                \"description\": \"طراحی مدرن با سایدبار کامل ۳ تبه المنتور و دکمه‌های مستقیم تسویه‌حساب.\",\n                \"metric_tag\": \"ویژه صفحات فرود\"\n              },\n              {\n                \"category_slug\": \"conversion\",\n                \"card_span\": \"span-1\",\n                \"icon\": \"⏳\",\n                \"title\": \"شمارنده اضطرار فروش (FOMO)\",\n                \"description\": \"ذخیره سشن در حافظه مرورگر جهت جلوگیری از ریست فریبنده.\",\n                \"metric_tag\": \"روانشناسی خرید\"\n              },\n              {\n                \"category_slug\": \"builder\",\n                \"card_span\": \"span-1\",\n                \"icon\": \"🧩\",\n                \"title\": \"کتابخانه تمپلیت‌های کانتینری و تم‌بیلدر\",\n                \"description\": \"هدر، فوتر، تک‌پست، محصول و آرشیو آماده درون‌ریزی با یک کلیک.\",\n                \"metric_tag\": \"۲۹+ الگوی بومی\"\n              },\n              {\n                \"category_slug\": \"speed\",\n                \"card_span\": \"span-2\",\n                \"icon\": \"🛡️\",\n                \"title\": \"معماری خالص Zero-CDN و هسته سبک PHP\",\n                \"description\": \"حذف کامل درخواست‌های شخص ثالث و دارایی‌های فونت خارجی جهت حداکثر رتبه سئو.\",\n                \"metric_tag\": \"Core Web Vitals A+\"\n              }\n            ]\n          }\n        }\n      ]\n    }\n  ]\n}"
