    "code": "{\n  \"version\": \"0.4\",\n  \"title\": \"UAS - صفحه خطای ۴۰۴ هوشمند و هدایت‌کننده (Theme Builder Error 404)\",\n  \"type\": \"single-page\",\n  \"content\": [\n    {\n      \"id\": \"uas_cnt_404_main\",\n      \"elType\": \"container\",\n      \"isInner\": false,\n      \"settings\": {\n        \"background_background\": \"gradient\",\n        \"background_color\": \"#0B1120\",\n        \"background_color_b\": \"#1E293B\",\n        \"padding\": {\n          \"unit\": \"px\",\n          \"top\": \"100\",\n          \"right\": \"20\",\n          \"bottom\": \"100\",\n          \"left\": \"20\"\n        },\n        \"content_width\": \"boxed\",\n        \"flex_direction\": \"column\",\n        \"flex_align_items\": \"stretch\",\n        \"flex_justify_content\": \"center\"\n      },\n      \"elements\": [\n        {\n          \"id\": \"uas_wid_404_code\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"heading\",\n          \"settings\": {\n            \"title\": \"۴۰۴\",\n            \"align\": \"center\",\n            \"header_size\": \"xl\"\n          }\n        },\n        {\n          \"id\": \"uas_wid_404_title\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"heading\",\n          \"settings\": {\n            \"title\": \"صفحه مورد نظر شما یافت نشد!\",\n            \"align\": \"center\",\n            \"header_size\": \"h2\"\n          }\n        },\n        {\n          \"id\": \"uas_wid_404_desc\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"text-editor\",\n          \"settings\": {\n            \"editor\": \"<p style='text-align:center; color:#94a3b8; font-size:16px; max-width:600px; margin:auto;'>متاسفانه آدرس وارد شده تغییر کرده یا حذف شده است. می‌توانید از طریق کادر جستجوی زیر مطلب مورد نظر خود را بیابید یا به صفحه اصلی بازگردید.</p>\"\n          }\n        },\n        {\n          \"id\": \"uas_wid_404_btn\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"button\",\n          \"settings\": {\n            \"text\": \"بازگشت به صفحه اصلی سایت\",\n            \"link\": {\n              \"url\": \"/\"\n            },\n            \"align\": \"center\",\n            \"size\": \"md\"\n          }\n        }\n      ]\n    }\n  ]\n}"
