    "code": "{\n  \"version\": \"0.4\",\n  \"title\": \"UAS - برگه اصلی مدرن و پرسرعت فرود (High-Converting SaaS Master Homepage)\",\n  \"type\": \"page\",\n  \"content\": [\n    {\n      \"id\": \"uas_cnt_home_hero\",\n      \"elType\": \"container\",\n      \"isInner\": false,\n      \"settings\": {\n        \"background_background\": \"gradient\",\n        \"background_color\": \"#0B132B\",\n        \"background_color_b\": \"#1C2541\",\n        \"padding\": {\n          \"unit\": \"px\",\n          \"top\": \"90\",\n          \"right\": \"20\",\n          \"bottom\": \"80\",\n          \"left\": \"20\"\n        },\n        \"content_width\": \"boxed\",\n        \"flex_direction\": \"column\",\n        \"flex_align_items\": \"stretch\",\n        \"flex_justify_content\": \"center\"\n      },\n      \"elements\": [\n        {\n          \"id\": \"uas_wid_home_hero\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"uas_hero\",\n          \"settings\": {\n            \"badge_text\": \"پلتفرم نسل جدید طراحی وب بدون کدنویسی\",\n            \"hero_title\": \"طراحی وب‌سایت‌های مدرن و خیره‌کننده، سریع‌تر از همیشه\",\n            \"hero_desc\": \"با مجموعه جامع ویجت‌ها و الگوهای آماده المنتور، در کمترین زمان صفحاتی زیبا با بیشترین نرخ تبدیل خلق کنید و زمان طراحی را به حداقل برسانید.\",\n            \"primary_btn_text\": \"شروع رایگان و مشاهده دموها\",\n            \"primary_btn_url\": {\n              \"url\": \"#pricing\",\n              \"is_external\": false\n            },\n            \"secondary_btn_text\": \"مشاهده کاتالوگ الگوها\",\n            \"secondary_btn_url\": {\n              \"url\": \"#features\",\n              \"is_external\": false\n            },\n            \"hero_image\": {\n              \"url\": \"https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&q=80&w=900\"\n            }\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"uas_cnt_home_features\",\n      \"elType\": \"container\",\n      \"isInner\": false,\n      \"settings\": {\n        \"padding\": {\n          \"unit\": \"px\",\n          \"top\": \"70\",\n          \"right\": \"20\",\n          \"bottom\": \"70\",\n          \"left\": \"20\"\n        },\n        \"content_width\": \"boxed\",\n        \"flex_direction\": \"column\",\n        \"flex_align_items\": \"stretch\",\n        \"flex_justify_content\": \"center\"\n      },\n      \"elements\": [\n        {\n          \"id\": \"uas_wid_home_features\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"uas_services_grid\",\n          \"settings\": {\n            \"section_badge\": \"قابلیت‌های انحصاری\",\n            \"section_title\": \"هر آنچه برای ساخت صفحات فرود موفق نیاز دارید\",\n            \"section_desc\": \"معماری فوق‌العاده سبک، بارگذاری فوق‌سریع و تطابق کامل با استانداردهای گوگل و سئو\",\n            \"columns\": \"3\",\n            \"items\": [\n              {\n                \"title\": \"سرعت بارگذاری فوق‌العاده\",\n                \"desc\": \"بدون بارگذاری فایل‌های سنگین جانبی، لود زیر ۱۰۰ میلی‌ثانیه و سازگار با کش سرور\",\n                \"icon\": \"eicon-flash\"\n              },\n              {\n                \"title\": \"امنیت و ساختار استاندارد\",\n                \"desc\": \"کدنویسی تمیز بر پایه استانداردهای رسمی وردپرس و اعتبارسنجی کامل داده‌ها\",\n                \"icon\": \"eicon-lock-user\"\n              },\n              {\n                \"title\": \"پشتیبانی کامل از زبان فارسی\",\n                \"desc\": \"چیدمان راست‌چین و چپ‌چین خودکار با قلم زیبا و بهینه‌سازی‌شده وزیرمتن\",\n                \"icon\": \"eicon-globe\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"uas_cnt_home_pricing\",\n      \"elType\": \"container\",\n      \"isInner\": false,\n      \"settings\": {\n        \"padding\": {\n          \"unit\": \"px\",\n          \"top\": \"60\",\n          \"right\": \"20\",\n          \"bottom\": \"60\",\n          \"left\": \"20\"\n        },\n        \"content_width\": \"boxed\",\n        \"flex_direction\": \"column\",\n        \"flex_align_items\": \"stretch\",\n        \"flex_justify_content\": \"center\"\n      },\n      \"elements\": [\n        {\n          \"id\": \"uas_wid_home_pricing\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"uas_vip_pricing\",\n          \"settings\": {\n            \"section_title\": \"پلن‌های سرمایه‌گذاری متناسب با مقیاس کار شما\",\n            \"section_subtitle\": \"بدون هزینه‌های پنهان، پرداخت امن و دسترسی مادام‌العمر به بسته‌ها\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"uas_cnt_home_faq\",\n      \"elType\": \"container\",\n      \"isInner\": false,\n      \"settings\": {\n        \"padding\": {\n          \"unit\": \"px\",\n          \"top\": \"50\",\n          \"right\": \"20\",\n          \"bottom\": \"70\",\n          \"left\": \"20\"\n        },\n        \"content_width\": \"boxed\",\n        \"flex_direction\": \"column\",\n        \"flex_align_items\": \"stretch\",\n        \"flex_justify_content\": \"center\"\n      },\n      \"elements\": [\n        {\n          \"id\": \"uas_wid_home_faq\",\n          \"elType\": \"widget\",\n          \"widgetType\": \"uas_faq\",\n          \"settings\": {\n            \"title\": \"پرسش‌های متداول طراحان و مدیران سایت\",\n            \"subtitle\": \"پاسخ سریع به متداول‌ترین سوالات درباره نصب و استفاده از ویجت‌ها\"\n          }\n        }\n      ]\n    }\n  ]\n}"
